package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import io.circe.Json

/**
 * TokenType defines the various types of tokens that can be generated.
 * Each type has a string value associated with it.
 */
sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

/**
 * Immutable token representation.
 */
case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  /**
   * Return a new token with additional metadata.
   * Follows the fluent pattern seen in the Python implementation.
   */
  def withMetadata(kwargs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kwargs.toMap)
  }
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer.empty[Token]
  private var _processed = false

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) {
      throw new IllegalStateException("Batch already processed")
    }
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Protocols (Traits in Scala)
// ============================================================================

/** Any object that can be converted to a token string. */
trait Tokenizable {
  def toToken: String
}

/** Any object with a length. */
trait HasLength {
  def length: Int
}

/** Contravariant processor that consumes tokens. */
trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/** Covariant container - can return subtypes. */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items

  def mapTokens(func: T => String): List[String] = _items.map(func).toList

  def size: Int = _items.size
}

/** Contravariant sink - can accept supertypes. */
class TokenSink[-T] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/** Invariant handler - exact type matching required. */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/** Abstract base tokenizer with generic input type. */
trait BaseTokenizer[T] {
  /** Convert value to token. */
  def tokenize(value: T): Token

  /** Lazy tokenization of multiple values. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/** Tokenizer for string and bytes types. */
class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s)  => s
      case Right(b) => new String(b, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }

  // Convenient overloads for direct use
  def tokenize(s: String): Token = tokenize(Left(s))
  def tokenize(b: Array[Byte]): Token = tokenize(Right(b))
}

/** Tokenizer for numeric types with precision handling. */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => s"%.${precision}f".format(d)
      case d: Double     => s"%.${precision}f".format(d)
      case f: Float      => s"%.${precision}f".format(f)
      case i: Int        => i.toString
      case l: Long       => l.toString
      case s: Short      => s.toString
      case b: Byte       => b.toString
      case other         => other.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

/** Tokenizer for date/time types. */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val ISO_FORMAT = "yyyy-MM-dd'T'HH:mm:ss"
  private val DATE_FORMAT = "yyyy-MM-dd"

  override def tokenize(value: Any): Token = {
    val fmtPattern = formatStr.getOrElse {
      value match {
        case _: LocalDateTime => ISO_FORMAT
        case _: LocalDate     => DATE_FORMAT
        case _                => ISO_FORMAT
      }
    }
    val formatter = DateTimeFormatter.ofPattern(fmtPattern)

    val strValue = value match {
      case dt: LocalDateTime => dt.format(formatter)
      case d: LocalDate      => d.format(formatter)
      case other             => other.toString
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Universal Tokenizer
// ============================================================================

/**
 * Tokenizer that handles multiple types with overloaded methods and runtime dispatch.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  /** Dispatch to appropriate tokenizer based on runtime type. */
  def tokenize(value: Any): Token = value match {
    case null            => tokenizeNull
    case t: Tokenizable   => Token(t.toToken, TokenType.STRUCTURED)
    case s: String       => stringTokenizer.tokenize(s)
    case b: Array[Byte]  => stringTokenizer.tokenize(b)
    case n: Int          => numericTokenizer.tokenize(n)
    case n: Long         => numericTokenizer.tokenize(n)
    case n: Float        => numericTokenizer.tokenize(n)
    case n: Double       => numericTokenizer.tokenize(n)
    case n: BigDecimal   => numericTokenizer.tokenize(n)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate    => temporalTokenizer.tokenize(d)
    case other           => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)
}

