/** Functor for tokens. */
class TokenFunctor[T](private val _value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(_value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(_value)

  def get: T = _value

  def getOrElse(default: T): T = if (_value != null) _value else default
}

/** Extended monad operations. */
class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  /** Applicative apply. */
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped.get(_value))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/** Tokenizer for JSON structures using Circe. */
class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  /** Extract and tokenize a value at a JSON path. */
  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split('.')
    val target = parts.foldLeft(Option(value)) { (current, part) =>
      current.flatMap { c =>
        if (c.isObject) {
          c.asObject.flatMap(_.apply(part))
        } else if (c.isArray && part.forall(_.isDigit)) {
          val idx = part.toInt
          c.asArray.flatMap(arr =>
            if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None
          )
        } else {
          None
        }
      }
    }
    target.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

/** Basic tokenizer that splits text by whitespace. */
class WhitespaceTokenizer(
    val lowercase: Boolean = false,
    val minLength: Int = 0,
    val maxLength: Option[Int] = None,
    val stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var w = if (stripPunctuation) {
      word.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    } else {
      word
    }

    if (lowercase) w = w.toLowerCase

    if (w.length < minLength) return None

    maxLength.foreach { max =>
      if (w.length > max) w = w.substring(0, max)
    }

    if (w.isEmpty) None else Some(w)
  }

  /** Split text by whitespace and return list of tokens. */
  def tokenize(text: String): List[Token] = {
    text.split("\\s+").filter(_.nonEmpty).zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  /** Convenience method that returns just the string values. */
  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  /** Tokenize text and return tokens with character positions. */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    var currentPos = 0
    val result = mutable.ListBuffer.empty[(String, Int, Int)]

    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      if (start != -1) {
        val end = start + word.length
        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }
        currentPos = end
      }
    }
    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

class TokenizerBuilder[T] {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kwargs: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kwargs
    this
  }

  /** Build the final tokenizer function. */
  def build(): T => Token = {
    val currentNormalizers = normalizers.toList
    val currentValidators = validators.toList
    val currentMetadata = metadata.toMap

    (value: T) => {
      currentValidators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString
      currentNormalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, currentMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]
}

